CREATE TABLE members (id TEXT PRIMARY KEY, google_sub TEXT NOT NULL UNIQUE, name TEXT NOT NULL, email TEXT NOT NULL, initials TEXT NOT NULL, color TEXT NOT NULL, created_at TEXT NOT NULL, is_owner INTEGER NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX one_owner ON members(is_owner) WHERE is_owner = 1;
CREATE TABLE invites (token_hash TEXT PRIMARY KEY, name TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, expires_at TEXT NOT NULL, used_by TEXT REFERENCES members(id), used_at TEXT);
CREATE TABLE bets (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, creator_id TEXT NOT NULL REFERENCES members(id), opponent_id TEXT NOT NULL REFERENCES members(id), winner_id TEXT REFERENCES members(id), stake INTEGER NOT NULL CHECK(stake BETWEEN 1 AND 100), status TEXT NOT NULL CHECK(status IN ('pending', 'active', 'confirming', 'owed', 'settling', 'settled', 'voided', 'declined')), version INTEGER NOT NULL CHECK(version > 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), CHECK(creator_id <> opponent_id), CHECK(winner_id IS NULL OR winner_id IN (creator_id, opponent_id)), CHECK(json_extract(data, '$.version') = version), CHECK(json_array_length(data, '$.events') = version));
CREATE TABLE events (id TEXT PRIMARY KEY, bet_id TEXT NOT NULL REFERENCES bets(id), version INTEGER NOT NULL, at TEXT NOT NULL, actor_id TEXT NOT NULL REFERENCES members(id), type TEXT NOT NULL, detail TEXT NOT NULL, UNIQUE(bet_id, version));
CREATE INDEX bets_participants ON bets(creator_id, opponent_id, status);
CREATE INDEX bets_status ON bets(status);
CREATE INDEX events_timeline ON events(bet_id, version);
CREATE INDEX invites_expiry ON invites(expires_at);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE oauth_states (state_hash TEXT PRIMARY KEY, browser_hash TEXT NOT NULL, nonce TEXT NOT NULL, verifier TEXT NOT NULL, invite_hash TEXT, expires_at TEXT NOT NULL);
CREATE INDEX oauth_states_expiry ON oauth_states(expires_at);
CREATE TRIGGER events_no_update BEFORE UPDATE ON events BEGIN SELECT RAISE(ABORT, 'Audit events are immutable'); END;
CREATE TRIGGER events_no_delete BEFORE DELETE ON events BEGIN SELECT RAISE(ABORT, 'Audit events are immutable'); END;
CREATE TRIGGER bets_insert_version BEFORE INSERT ON bets WHEN NEW.version <> 1 BEGIN SELECT RAISE(ABORT, 'A bet must begin at version 1'); END;
CREATE TRIGGER bets_update_version BEFORE UPDATE ON bets WHEN NEW.version <> OLD.version + 1 BEGIN SELECT RAISE(ABORT, 'Bet version must increase by one'); END;
CREATE TRIGGER bets_append_history BEFORE UPDATE ON bets WHEN json_remove(NEW.data, '$.events[#-1]')->'$.events' <> OLD.data->'$.events' BEGIN SELECT RAISE(ABORT, 'Prior audit history is immutable'); END;
CREATE TRIGGER bets_created AFTER INSERT ON bets BEGIN INSERT INTO events (id, bet_id, version, at, actor_id, type, detail) VALUES (json_extract(NEW.data, '$.events[#-1].id'), NEW.id, NEW.version, json_extract(NEW.data, '$.events[#-1].at'), json_extract(NEW.data, '$.events[#-1].actorId'), json_extract(NEW.data, '$.events[#-1].type'), json_extract(NEW.data, '$.events[#-1].detail')); END;
CREATE TRIGGER bets_updated AFTER UPDATE ON bets BEGIN INSERT INTO events (id, bet_id, version, at, actor_id, type, detail) VALUES (json_extract(NEW.data, '$.events[#-1].id'), NEW.id, NEW.version, json_extract(NEW.data, '$.events[#-1].at'), json_extract(NEW.data, '$.events[#-1].actorId'), json_extract(NEW.data, '$.events[#-1].type'), json_extract(NEW.data, '$.events[#-1].detail')); END;
CREATE VIEW outstanding_obligations AS SELECT id AS bet_id, CASE WHEN winner_id = creator_id THEN opponent_id ELSE creator_id END AS from_id, winner_id AS to_id, stake AS rolls FROM bets WHERE status IN ('owed', 'settling') AND winner_id IS NOT NULL;
CREATE VIEW member_statistics AS SELECT m.id AS member_id, COUNT(CASE WHEN b.winner_id = m.id THEN 1 END) AS wins, COUNT(CASE WHEN b.winner_id <> m.id THEN 1 END) AS losses, COALESCE(SUM(CASE WHEN b.winner_id = m.id THEN b.stake ELSE 0 END), 0) AS rolls_won, COALESCE(SUM(CASE WHEN b.winner_id <> m.id THEN b.stake ELSE 0 END), 0) AS rolls_lost FROM members m LEFT JOIN bets b ON m.id IN (b.creator_id, b.opponent_id) AND b.status IN ('owed', 'settling', 'settled') AND b.winner_id IS NOT NULL GROUP BY m.id;
